//! Cold CPU-only source curve-coordinate protocol, not native GPU acceptance.
#[path="../src/annotation_widget_primitives.rs"]mod primitives;
fn main(){let path=std::env::args().nth(1).expect("oracle JSON");let value:serde_json::Value=serde_json::from_slice(&std::fs::read(path).unwrap()).unwrap();let rows=value["cases"].as_array().unwrap();let out:Vec<_>=rows.iter().map(|row|{let op=&row["operations"][0];let pair=|key:&str|std::array::from_fn(|i|op[key][i].as_f64().unwrap());let fan=if op["stroke"].as_bool()==Some(true){primitives::ellipse_stroke(pair("center"),pair("radius"),op["width"].as_f64().unwrap(),1.).unwrap()}else{primitives::ellipse_fill(pair("center"),pair("radius"),1.).unwrap()};serde_json::json!({"name":row["name"],"positions":fan,"bits":fan.iter().map(|p|p.map(f32::to_bits)).collect::<Vec<_>>()})}).collect();println!("{}",serde_json::to_string_pretty(&out).unwrap());}
